DEFAULT_AZURE_TENANT_ID = "ca56a4a5-e300-406a-98ff-7e36a0baac5b"
DEFAULT_METIQ_ENDPOINT = "https://internal.apis.metlife.com/channel/metiq/webapi"
DEFAULT_AZURE_AUTHORITY = f"https://login.microsoftonline.com/{DEFAULT_AZURE_TENANT_ID}"
DEFAULT_METIQ_CA_BUNDLE = os.path.expanduser("~/.certs/ca_cert.crt")

class MetIQCertificate(BaseModel):
    certificate_path: str
    certificate_password: Optional[SecretStr] = None
    certificate_scope: Optional[str] = None
    certificate_tenant: Optional[str] = DEFAULT_AZURE_TENANT_ID

class MetIQConfig(BaseModel):
    use_case_id: str
    client_id: Optional[str] = None
    ca_bundle: Optional[str] = None
    subscription_key: Optional[SecretStr] = None
    endpoint: Optional[str] = None
    certificate_config: Optional[MetIQCertificate] = None
    model_config = ConfigDict(
        arbitrary_types_allowed=True,
        extra="allow",
    )

    @model_validator(mode="before")
    def validate_environment(cls, values: dict) -> "MetIQConfig":
        values["endpoint"] = get_from_dict_or_env(
            values, "endpoint", "METIQ_ENDPOINT", default=DEFAULT_METIQ_ENDPOINT
        )
        values["use_case_id"] = get_from_dict_or_env(
            values, "use_case_id", "METIQ_USE_CASE_ID"
        )
        values["ca_bundle"] = get_from_dict_or_env(
            values, "ca_bundle", "METIQ_CA_BUNDLE", default=DEFAULT_METIQ_CA_BUNDLE
        )
        values["subscription_key"] = convert_to_secret_str(
            get_from_dict_or_env(values, "subscription_key", "AZURE_SUBSCRIPTION_KEY")
        )
        values["client_id"] = get_from_dict_or_env(
            values, "client_id", "AZURE_CLIENT_ID"
        )
        if values.get("certificate_config"):
            certificate_config = values["certificate_config"]
            values["api"] = MetIQAPI  (
                values["endpoint"],
                values["client_id"],
                values["subscription_key"].get_secret_value(),
                verify=values["ca_bundle"],
                certificate_path=certificate_config.certificate_path,
                certificate_password=certificate_config.certificate_password.get_secret_value() if certificate_config.certificate_password else None,
                certificate_scope=certificate_config.certificate_scope,
                certificate_tenant=certificate_config.certificate_tenant
            )
        elif values.get("session"):
            print("CONFIGURING WITH SESSION")
            values["api"] = MetIQAPI(
                values["endpoint"], 
                values["client_id"], 
                values["subscription_key"].get_secret_value(), 
                session=values["session"] 
            )
        else:
            values["api"] = MetIQAPI(
                values["endpoint"],
                values["client_id"],
                values["subscription_key"].get_secret_value(),
                verify=values["ca_bundle"]
            )
        
        return values  # type: ignore


class MetIQ(LLM):
    config: MetIQConfig
    api_version: Literal["v1", "v2"] = "v1"
    auto_execute_tools: bool = True

    def settings(self):
        return self.config.api.get_usecase_settings(self.config.use_case_id)

    def search(self, input, filters=[], history=[]):
        raise NotImplementedError("""Search is supported by the MetIQ API directly. If you need to search a use-case, please use the MetIQ API directly:
                        ```python
from metiq_api import MetIQAPI
api = MetIQAPI("https://dev.internal.apis.metlife.com/channel/metiq/webapi", "your_client_id", "your_subscription_key")
api.search("use_case_id", "search_term")
```""")
    
    def _chat_v1(self, input, filters=[], history=[]):
        payload = {
            "prompt": {
                "role": "Human",
                "content": input,
                "intent": ""
            },
            "history": history,
            "filters": filters
        }
        resp = self.config.api.chat(self.config.use_case_id, payload)
        try:
            content = resp.pop("content")
        except KeyError:
            raise ValueError(f"Invalid response from MetIQ: {resp}")
        generation = ChatGeneration(message=AIMessage(content=content, additional_kwargs={"filters":filters, "history": history}, response_metadata=resp))
        return ChatResult(generations=[generation])    
    
    def _normalize_v2_parts(self, input: Any) -> List[Dict[str, Any]]:
        # Allow callers to pass parts directly.
        if isinstance(input, list) and all(isinstance(p, dict) for p in input):
            return input  # assume already v2 part objects

    def _build_v2_prompt(self, input_content: Any) -> Dict[str, Any]:
        """
        Build a v2 prompt structure with Text type.
        
        Args:
            input_content: The content (can be string or other types).
            
        Returns:
            dict: A v2 prompt structure with role and parts.
        """
        if isinstance(input_content, dict) and "role" in input_content and "parts" in input_content:
            return input_content  # assume already a v2 prompt
        elif isinstance(input_content, list) and all(isinstance(p, dict) for p in input_content):
            return {
                "role": "User",
                "parts": input_content,
            }
        else:
            return {
                "role": "User",
                "parts": [{"content": str(input_content), "type": "Text"}],
            }

    def execute_tool_calls(self, tool_calls, tool_registry):
        # Execute tools locally
        tool_call_responses = []
        for tool_call in tool_calls:
            call_id = tool_call.get("id")
            func_name = tool_call.get("name")
            args_json = tool_call.get("argumentJson", "{}")
            
            logging.debug("Executing tool: %s with args: %s", func_name, args_json)
            
            if func_name not in tool_registry:
                logging.error("Tool '%s' not found in registry", func_name)
                tool_call_responses.append({
                    "id": call_id,
                    "content": json.dumps({"error": f"Tool '{func_name}' not found"}),
                })
                continue
            
            try:
                # Parse arguments
                args = json.loads(args_json)
                
                # Execute function
                func = tool_registry[func_name]
                result = func(**args) if isinstance(args, dict) else func(args)
                
                # Convert result to JSON string
                result_json = json.dumps(result) if not isinstance(result, str) else result
                
                tool_call_responses.append({
                    "id": call_id,
                    "content": result_json,
                })
                
                logging.debug("Tool '%s' executed successfully: %s", func_name, result_json)
                
            except Exception as e:
                logging.error("Error executing tool '%s': %s", func_name, str(e))
                tool_call_responses.append({
                    "id": call_id,
                    "content": json.dumps({"error": str(e)}),
                })
        return tool_call_responses
    
    def _chat_v2(
        self,
        input: Any,
        functions: Optional[List[Dict[str, Any]]] = None,
        history: Optional[List[Dict[str, Any]]] = None,
        filters: Optional[Dict[str, Any]] = None,
        tool_registry: Optional[Dict[str, Callable]] = None,
        auto_execute_tools: bool = True,
    ) -> ChatResult:
        """
        Perform a v2 chat operation with support for function calling.
        
        This is the main entry point for v2 API. It handles:
        - Plain chat (no functions)
        - Function calling with automatic two-step execution
        
        Args:
            usecase_id (str): The ID of the use case.
            input: The user input (will be converted to v2 format).
            functions (list, optional): List of function definitions. Each can include:
                - name: Function name
                - description: Function description
                - parametersSchema: JSON schema as string
                - callable/impl/handler: Local Python function (stripped before API call)
            history (list, optional): Conversation history in v2 format.
            filters (dict, optional): Additional filters.
            groundings (list, optional): List of grounding IDs (knowledge base or document collection IDs).
            tool_registry (dict, optional): Manual tool registry {name: callable}.
                Note: If functions contain embedded callables, those take precedence.
            auto_execute_tools (bool): If True, automatically execute tools and send
                results back (two-step flow). Default: True.
                
        Returns:
            dict: The API response (final answer if two-step, or step1 if no tools).
            
        Raises:
            ValueError: If MetIQ returns toolCalls but no executor is available.
        """
    
        v2_prompt = self._build_v2_prompt(input)
        # Build payload
        payload = {
            "prompt": v2_prompt,
            "history": history or [],
            "filters": filters or {},
            "groundings": []
        }
        
        if functions:
            payload["functions"] = functions
        
        try:
            step1_response = self.config.api.chat_v2(self.config.use_case_id, payload)            
        except Exception as e:
            logging.error("V2 Step 1 request failed: %s", str(e))
            raise
        

        # Check if MetIQ returned toolCalls
        tool_calls = step1_response.get("toolCalls")
        if tool_calls:
            if not auto_execute_tools:
                logging.info("Received toolCalls but auto_execute_tools=False. Returning step1 response.")
                result = ChatResult(generations=[ChatGeneration(
                    message=AIMessage(
                        content=step1_response.get("content", ""),
                        additional_kwargs={
                            "filters": filters,
                            "history": history
                        },
                        response_metadata=step1_response
                    )
                )])
                return result
                
            if not tool_registry:
                raise ValueError(
                    "MetIQ returned toolCalls but no tool executor is available. "
                    "Provide 'tool_registry'."
                )
            
            tool_call_responses = self.execute_tool_calls(tool_calls, tool_registry)

            # Build updated history
            updated_history = history.copy() if history else []
            
            # Add agent turn with toolCalls
            agent_turn = {
                "role": "Agent",
                "id": step1_response.get("id"),
                "toolCalls": tool_calls,
                "content": step1_response.get("content"),
                "created": step1_response.get("created", "0001-01-01T00:00:00+00:00"),
            }
            updated_history.append(agent_turn)
            
            # Add toolCallResponses
            updated_history.append({"toolCallResponses": tool_call_responses})

            payload_2 = {
                "prompt": v2_prompt,
                "history": updated_history or [],
                "filters": filters or {},
                "groundings": []
            }

            # Execute two-step flow
            logging.info("Executing second call to metiq_api.chat_v2 with toolCallResponses")
            try:
                step2_response = self.config.api.chat_v2(self.config.use_case_id, payload_2)
                
                result = ChatResult(generations=[ChatGeneration(
                    message=AIMessage(
                        content=step2_response.get("content", ""),
                        additional_kwargs={
                            "filters": filters,
                            "history": updated_history
                        },
                        response_metadata=step2_response
                    )
                )])
                return result
            except Exception as e:
                logging.error("V2 Step 2 request failed: %s", str(e))
                raise
        
        # No tool calls, return final response
        result = ChatResult(generations=[ChatGeneration(
            message=AIMessage(
                content=step1_response.get("content", ""),
                additional_kwargs={
                    "filters": filters,
                    "history": history
                },
                response_metadata=step1_response
            )
        )])
        return result

    def chat(self, input, filters=None, history=[], api_version=None, functions=None, tool_registry=None, auto_execute_tools=None):
        # Use instance defaults if not specified
        if api_version is None:
            api_version = self.api_version
        if auto_execute_tools is None:
            auto_execute_tools = self.auto_execute_tools
            
        if filters is None:
            filters = {} if api_version == "v2" else []
            
        if api_version == "v1":
            logging.info("Using v1 chat API")
            return self._chat_v1(input, filters, history)
        elif api_version == "v2":
            logging.info("Using v2 chat API")
            return self._chat_v2(input, functions, history, filters, tool_registry, auto_execute_tools)
        else:
            raise ValueError(f"Unsupported API version: {api_version}")

    def _call(
        self,
        prompt: str,
        stop: Optional[List[str]] = None,
        run_manager: Optional[CallbackManagerForLLMRun] = None,
        **kwargs: Any,
    ) -> str:
        """Run the LLM on the given input.

        Override this method to implement the LLM logic.

        Args:
            prompt: The prompt to generate from.
            stop: Stop words to use when generating. Model output is cut off at the
                first occurrence of any of the stop substrings.
                If stop tokens are not supported consider raising NotImplementedError.
            run_manager: Callback manager for the run.
            **kwargs: Arbitrary additional keyword arguments. These are usually passed
                to the model provider API call.

        Returns:
            The model output as a string. Actual completions SHOULD NOT include the prompt.
        """
        # if stop is not None:
        #     raise ValueError("stop kwargs are not permitted.")
        
        # Use instance defaults if not overridden in kwargs
        api_version = kwargs.get("api_version", self.api_version)
        filters = kwargs.get("filters")
        if filters is None:
            filters = {} if api_version == "v2" else [] 
        history = kwargs.get("history", [])
        tool_registry = kwargs.get("tool_registry")
        functions = kwargs.get("functions")
        auto_execute_tools = kwargs.get("auto_execute_tools", self.auto_execute_tools)

        resp = self.chat(
            input=prompt,
            history=history,
            filters=filters,
            api_version=api_version,
            functions=functions,
            tool_registry=tool_registry,
            auto_execute_tools=auto_execute_tools
        )
        return resp.generations[0].text

